  [437169] = { "Inizia un rituale che crea un portale di evocazione. Il portale di evocazione può essere usato da $N1 membri del gruppo o dell'incursione per evocare un membro del gruppo o dell'incursione selezionato. Per completare il portale del rituale servono l'incantatore e altri $N2 membri del gruppo o dell'incursione. Per partecipare, tutti i giocatori devono essere fuori dal combattimento, cliccare con il tasto destro sul portale e restare fermi finché il rituale non è completato.", nil, 0xc8e21a4f, nil, "um" },
  [437280] = { "Porta il personaggio a Gnomeregan.", nil, 0x187b8984, nil, "um" },
