  [437301] = { "L'incantatore concentra nubi di torpore intorno ai bersagli.", nil, 0x2cebc54f, nil, "um" },
  [437311] = { "Inizia un rituale che crea un portale di evocazione. Il portale di evocazione può essere usato da $N1 membri del gruppo o dell'incursione per evocare un membro del gruppo o dell'incursione selezionato. Per completare il portale del rituale servono l'incantatore e altri $N2 membri del gruppo o dell'incursione. Per partecipare, tutti i giocatori devono essere fuori dal combattimento, cliccare con il tasto destro sul portale e restare fermi finché il rituale non è completato.", nil, 0xc8e21a4f, nil, "um" },
  [437324] = { "Entrare in contatto con una nube di torpore fa addormentare il bersaglio per $D1, riducendo del $N2% i danni che subisce e le cure che riceve.", "Stordito.\nDanni subiti ridotti del $N1%.\nCure ricevute ridotte del $N2%.", 0x6f67d095, 0xb910554a, "uu" },
  [437327] = { "Sfrutta l'energia arcana latente nell'aria circostante per ottenere un'ispirazione carica, che riduce del $N1% il costo in mana di tutti gli incantesimi e aumenta fino a $N2 i danni e le cure prodotti per $D1.", "Hai ottenuto un'ispirazione carica. Il costo in mana di tutti gli incantesimi è ridotto e la potenza magica è aumentata.", 0x24c5eb1b, 0xf61c90bd, "uu" },
  [437340] = { "Attiva i protocolli di attenuazione delle radiazioni di questo elmo, rimuovendo all'istante tutti gli effetti di veleno attivi e rendendoti immune a tutti i danni da natura per $D1.", "Immune ai danni da natura.", 0x4ebeb267, 0x68bd12e9, "uu" },
  [437349] = { "Provoca uno shock gneurologico che ti infligge all'istante $N1 danni ma aumenta anche del $N2% la tua velocità d'attacco in mischia e a distanza per $D1.", "Velocità d'attacco aumentata.", 0xef371b03, 0x13f57478, "uu" },
  [437353] = { "L'incantatore soffia un'ondata di magia corrosiva sul bersaglio, infliggendo $N1 danni da natura e riducendone l'Armatura del $N2% per $D1.", "Armatura ridotta del $N1%.", 0x2858ba79, 0x7bc85918, "uu" },
  [437357] = { "Ottieni una meditazione gneuromantica che permette al $N1% della tua rigenerazione del mana di continuare durante il lancio e aumenta fino a $N2 i danni e le cure prodotti dagli incantesimi per $D1.", "Potenza magica aumentata e rigenerazione del mana durante il lancio.", 0x86098cef, 0x03b0eb0f, "uu" },
  [437362] = { "Provoca uno shock iperconduttivo che ti infligge all'istante $N1 danni ma aumenta anche del $N2% la tua velocità di lancio degli incantesimi per $D1.", "Velocità di lancio aumentata.", 0x8d58fca5, 0x18ca25de, "uu" },
  [437367] = { "Dopo un blocco riuscito, gli ingranaggi rotanti e affilatissimi di questo scudo infliggono $N1 danni fisici all'attaccante e $N2 danni fisici a chi lo porta.", nil, 0x725e04a5, nil, "um" },
  [437368] = { "Estrai dalla cintura una moneta iperconduttiva e lanciala. Testa: la tua probabilità di critico con tutti gli incantesimi e gli attacchi aumenta del $N1% per $D1. Croce: la tua velocità di movimento aumenta del $N3% per $D2.", nil, 0xc6aaecf9, nil, "um" },
  [437375] = { "Infligge $N1 danni ai bersagli dietro l'incantatore, respingendoli indietro.", nil, 0x16a70bcb, nil, "um" },
  [437377] = { "Ottieni una concentrazione intensa che riduce del $N1% la velocità di movimento, ma aumenta di $N2 la resistenza agli incantesimi di tutte le scuole e del $N3% la velocità d'attacco in mischia per $D1.", "Concentrazione intensa. Velocità d'attacco e resistenza agli incantesimi aumentate, ma velocità di movimento ridotta.", 0x9e0e0337, 0xce9fc031, "uu" },
  [437382] = { "Ottieni una forza di volontà rinforzata che ti protegge da Silenzio, dagli effetti d'interruzione e dal ritardo di lancio per $D1.", "Immune a Silenzio, agli effetti d'interruzione e al ritardo di lancio.", 0x408a3327, 0x1b35000d, "uu" },
  [437390] = { "L'incantatore sputa un veleno letargico sui giocatori, infliggendo $N1 danni da natura ogni $D1 per $D2. Questo veleno riduce del $N4% la probabilità di colpire e aumenta del $N5% il costo delle abilità.", "$N1 danni da natura inflitti ogni $D1.\nProbabilità di colpire ridotta del $N3%.\nCosto delle risorse aumentato del $N4%.", 0xffb190ae, 0xea77cfb5, "uu" },
